"""Generate docs/final_numbers_v11c.md from committed v11c result files."""
import json, subprocess
from pathlib import Path
import pandas as pd
ROOT = Path(__file__).resolve().parents[2]
f = lambda x, n=4: f"{x:.{n}f}"
ad_new = json.loads((ROOT / "results/v5/BASE/delta_freeze_adopt/readings.json").read_text())
ad_old = json.loads(subprocess.check_output(["git", "show", "ead4933:results/v5/BASE/delta_freeze_adopt/readings.json"], cwd=ROOT))
sd = json.loads((ROOT / "results/v11/seed_avg.json").read_text())
ens = pd.read_csv(ROOT / "results/v11/ensemble/best_per_property.csv")
rf = pd.read_csv(ROOT / "results/v11/rf_pure/summary.csv")
miss = pd.read_csv(ROOT / "results/v11/lock_missing_constants.csv")
o = ["# v11c final numbers: minor optimisations", "", "Generated by `scripts/v11/build_final_numbers_v11c.py` from `results/v11/` and `results/v5/BASE/delta_freeze_adopt/` (earlier values read from commit ead4933). Rules: `docs/v11c_predeclaration.md`.", "",
     "## 1. o-/m-xylene eutectic correction (applied)", "",
     "Entered 66.6 percent o / 33.4 percent m; ideal Schroeder-van Laar at 211.2 K from the paper's Tm and dHfus gives about 32 percent o / 66 percent m, so the percentages were transposed and are corrected in `ingest_calorimetry_primary.py` (checked by consistency, not against the page image). Lab liquidus S_F, 12 systems, 73 points:", "",
     "| route | MAE before | MAE after | margin before | margin after |", "|---|---|---|---|---|"]
def find(d, key):
    if isinstance(d, dict):
        if key in d: return d[key]
        for v in d.values():
            r = find(v, key)
            if r is not None: return r
for k in ("ideal", "unifac"):
    o.append(f"| {k} | {f(find(ad_old, f'mae_{k}_C'))} | {f(find(ad_new, f'mae_{k}_C'))} | unchanged | unchanged (16.975 ideal, 13.843 UNIFAC) |")
o += ["", "Margins are the worst-error order statistics over 12 systems and did not move. The frozen scoreboard is unchanged (reproduce_base: 0 changed files). Designs were not re-run.", "",
      "## 2. v9 density systems (item 2): nothing to add", "", "The only v9 density binary system absent from v5 (2c635cfd3548, 45 rows) is in the v9 lock, so it stays held out. The inventory count of 4 new systems includes systems already in v5 that gained new points.", "",
      "## 3. Seed averaging (5 seeds), outer dev folds", "", "| model | single seed MAE | 5-seed MAE | gain | 95 % interval | adopted |", "|---|---|---|---|---|---|"]
for k, r in sd.items():
    o.append(f"| {k} | {f(r['mae_single'])} | {f(r['mae_avg5'])} | {f(r['gain'])} | {f(r['lo'])} to {f(r['hi'])} | {r['adopt']} |")
o += ["", "## 4. Viscosity warm-only hybrid (post hoc)", "", "Evaluated from the v11b out-of-fold numbers (`docs/final_numbers_v11.md`): warm gain 0.0021 ln, interval 0.0002 to 0.0041, warm margin 0.1343 to 0.1258; cold bins unchanged by construction. Not applied: it would shift viscosity values in the design runs and the choice was made after seeing the guard failure. Status: not adopted.", "",
      "## 5a. Ensembles of the deployed pure-compound models (saved scaffold-CV predictions)", "", "| property | deployed | best ensemble | MAE deployed | MAE ensemble | gain | 95 % interval | Holm p | adopted |", "|---|---|---|---|---|---|---|---|---|"]
for r in ens.itertuples():
    o.append(f"| {r.property} | {r.deployed} | {r.ensemble} | {f(r.mae_deployed,3)} | {f(r.mae_ensemble,3)} | {f(r.gain,3)} | {f(r.lo,3)} to {f(r.hi,3)} | {f(r.p_holm,3)} | {r.adopt} |")
o += ["", "The ensemble per property is the lower-MAE of two candidates, so the interval is mildly optimistic; none passes.", "", "## 5b. Nested tuning of the random forest (20 trials per outer fold)", "", "| property | MAE v7 RF | MAE tuned RF | gain | 95 % interval | Holm p | adopted |", "|---|---|---|---|---|---|---|"]
for r in rf.itertuples():
    o.append(f"| {r.property} | {f(r.mae_rf_v7,3)} | {f(r.mae_rf_tuned,3)} | {f(r.gain,3)} | {f(r.lo,3)} to {f(r.hi,3)} | {f(r.p_holm,3)} | {r.adopt} |")
o += ["", "## 6. Fresh flash lock constants (not done)", "", f"{len(miss)} of the 40 lock compounds lack both Antoine constants and LFL (list: `results/v11/lock_missing_constants.csv`, mostly alcohols, esters, ketones and phenol). Verified constants for them are a data task like v9 and v10 and were not attempted; estimated constants would break the lock rule that nothing is fitted before scoring. Status: not scorable.", "",
      "Overall: one correction applied (item 1, margins unchanged); no tuned or ensembled model adopted in this round."]
(ROOT / "docs/final_numbers_v11c.md").write_text("\n".join(o) + "\n", encoding="utf-8")
print("ok")
